integration.assetPreloadJs:
const m = this.cache.json.get('ilha_farol_manifest');
for (const a of m.assets) {
  this.load.atlas(a.textureKey, m.integration.assetBasePath + a.imageFile, a.atlas);
}

integration.createAnimationsJs:
const m = this.cache.json.get('ilha_farol_manifest');
for (const config of m.phaserAnimations.anims) {
  if (!this.anims.exists(config.key)) this.anims.create(config);
}
